/* Generated by port_site.py from the approved mockup. Behaviour for the ads section; timers, listeners and observers go through ctx. */
export function init(ctx) {
  var reduce = ctx.reduce;
  /* words fill as the statement scrolls through the view; then the money trail draws and the revenue counts up (framer-motion scroll) */
  var aw = [].slice.call(document.querySelectorAll("#adsec .aw")),
    nodes = [].slice.call(document.querySelectorAll("#trail .tnode")),
    line = document.querySelector("#trail .tline i"),
    rev = document.getElementById("adrev"),
    TARGET = 50600,
    scroll = ctx.Motion.scroll;
  function rupees(n) {
    return "₹" + Math.round(n).toLocaleString("en-IN");
  }
  function words(p) {
    var lit = Math.round(p * aw.length);
    aw.forEach(function (w, i) {
      w.style.color =
        i < lit ? (w.classList.contains("gold") ? "#F3D27A" : "#EAF6F4") : "";
    });
  }
  function trail(pr) {
    line.style.transform = "scaleX(" + pr + ")";
    nodes.forEach(function (n, i) {
      n.classList.toggle("on", pr >= i / (nodes.length - 1) - 0.02);
    });
    rev.textContent = rupees(
      TARGET * Math.max(0, Math.min(1, (pr - 0.66) / 0.34)),
    );
  }
  if (reduce || !scroll) {
    words(1);
    trail(1);
    return;
  }
  rev.textContent = rupees(0);
  ctx.cleanup(
    scroll(words, {
      target: document.querySelector("#adsec .adsay"),
      offset: ["start 0.88", "start 0.5"],
    }),
  );
  ctx.cleanup(
    scroll(trail, {
      target: document.getElementById("trail"),
      offset: ["start 0.95", "start 0.72"],
    }),
  );
}
